package ncasa.expense.infrastructure.scheduling;
import ncasa.expense.application.occurrence.MaterializeDueExpensePlanUseCase;import ncasa.expense.application.reminder.PublishDueExpensePlanReminderUseCase;import ncasa.expense.domain.ExpensePlanId;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ExpensePlanJobRunner{private final MaterializeDueExpensePlanUseCase materializer;private final PublishDueExpensePlanReminderUseCase reminders;public ExpensePlanJobRunner(MaterializeDueExpensePlanUseCase m,PublishDueExpensePlanReminderUseCase r){materializer=m;reminders=r;}@Transactional public void materialize(ExpensePlanId id){materializer.execute(id);}@Transactional public void remind(ExpensePlanId id){reminders.execute(id);}}
